"use client";

import React, { useState, useRef, useEffect } from "react";
import Image from "next/image";
import Idea from "@/public/icons/idea.svg";
import Business from "@/public/icons/business.svg";
import BusinessLogo from "@/public/icons/business-logo.svg";
import AV from "@/public/icons/av.svg";

const BusinessNameGenerator = () => {
    const [inputValue, setInputValue] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [chatActive, setChatActive] = useState(false);
    const [selectedOption, setSelectedOption] = useState("");
    const [messages, setMessages] = useState([]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!inputValue.trim()) return;

        // Add user message to chat
        const userMessage = inputValue;
        setMessages([...messages, { type: 'user', content: userMessage }]);

        // Clear input and show loading state
        setInputValue("");
        setIsLoading(true);

        // Set chat to active if this is the first message
        if (!chatActive) {
            setChatActive(true);

            // If no specific option was selected yet, determine from input
            if (!selectedOption) {
                if (userMessage.toLowerCase().includes("logo")) {
                    setSelectedOption("logo");
                } else if (userMessage.toLowerCase().includes("name")) {
                    setSelectedOption("name");
                } else if (userMessage.toLowerCase().includes("prd")) {
                    setSelectedOption("prd");
                }
            }
        }

        // Simulate AI response
        setTimeout(() => {
            let aiResponse = "";

            // Generate appropriate response based on the first message or selected option
            if (selectedOption === "logo" || userMessage.toLowerCase().includes("logo")) {
                aiResponse = "I'd be happy to help you create a logo for your business! To get started, I'll need some information about your business to develop a concept that represents your brand effectively.\n\nCould you share:\n\n1. Your business name\n2. The industry or type of business\n3. Any specific colours, symbols, or elements you'd like to include\n4. The overall feeling or impression you want your logo to convey\n5. Where you plan to use the logo (website, social media, signage, etc.)\n\nWith these details, I can help design an SVG logo that will work well across different platforms and sizes. I can provide you with the code that you can then use or further refine with a graphic designer.";
            } else if (selectedOption === "name" || userMessage.toLowerCase().includes("name")) {
                aiResponse = "I'd be happy to help you find the perfect name for your business! To create meaningful suggestions, I'll need some information about your business concept.\n\nCould you please share:\n\n1. What industry or market your business will operate in\n2. Your target audience or customer base\n3. The key products or services you'll offer\n4. Any specific values, emotions, or qualities you want the name to evoke\n5. Any naming style preferences (e.g., modern, classic, playful, serious)\n\nWith these details, I can generate a list of business name ideas that align with your vision and have available domain names.";
            } else if (selectedOption === "prd" || userMessage.toLowerCase().includes("prd")) {
                aiResponse = "I'd be happy to help you create a Product Requirements Document (PRD) for your startup idea! To make this as valuable as possible, I'll need some details about your concept.\n\nCould you please share:\n\n1. A brief description of your product idea\n2. The primary problem it solves for users\n3. Your target audience\n4. Key features you envision\n5. Any competitors or similar solutions in the market\n\nWith this information, I can create a structured PRD that includes product overview, user personas, functional requirements, non-functional requirements, and success metrics to guide your product development.";
            } else {
                aiResponse = "Thanks for your message! Would you like help with creating a logo, finding a business name, or developing a PRD for your startup idea? I can help with any of these - just let me know what you need!";
            }

            setMessages([...messages, { type: 'user', content: userMessage }, { type: 'ai', content: aiResponse }]);
            setIsLoading(false);
        }, 1000);
    };

    const handleOptionSelect = (option) => {
        setSelectedOption(option);
        setChatActive(true);

        // Generate initial AI message based on selected option
        let aiResponse = "";
        if (option === "logo") {
            aiResponse = "I'd be happy to help you create a logo for your business! To get started, I'll need some information about your business to develop a concept that represents your brand effectively.\n\nCould you share:\n\n1. Your business name\n2. The industry or type of business\n3. Any specific colours, symbols, or elements you'd like to include\n4. The overall feeling or impression you want your logo to convey\n5. Where you plan to use the logo (website, social media, signage, etc.)\n\nWith these details, I can help design an SVG logo that will work well across different platforms and sizes. I can provide you with the code that you can then use or further refine with a graphic designer.";
        } else if (option === "name") {
            aiResponse = "I'd be happy to help you find the perfect name for your business! To create meaningful suggestions, I'll need some information about your business concept.\n\nCould you please share:\n\n1. What industry or market your business will operate in\n2. Your target audience or customer base\n3. The key products or services you'll offer\n4. Any specific values, emotions, or qualities you want the name to evoke\n5. Any naming style preferences (e.g., modern, classic, playful, serious)\n\nWith these details, I can generate a list of business name ideas that align with your vision and have available domain names.";
        } else if (option === "prd") {
            aiResponse = "I'd be happy to help you create a Product Requirements Document (PRD) for your startup idea! To make this as valuable as possible, I'll need some details about your concept.\n\nCould you please share:\n\n1. A brief description of your product idea\n2. The primary problem it solves for users\n3. Your target audience\n4. Key features you envision\n5. Any competitors or similar solutions in the market\n\nWith this information, I can create a structured PRD that includes product overview, user personas, functional requirements, non-functional requirements, and success metrics to guide your product development.";
        }

        setMessages([{ type: 'ai', content: aiResponse }]);
    };

    return (
        <div className="min-h-screen bg-black text-white flex flex-col">
            {/* Main Content */}
            <div className="flex-1 flex flex-col items-center justify-center px-4 py-16">
                {!chatActive ? (
                    /* Welcome Screen - Shown when chat is not active */
                    <>
                        {/* Hero Section */}
                        <div className="max-w-3xl w-full text-center mb-16">
                            <h1 className="text-4xl md:text-4xl mb-6">
                                Harness the power of AI. Describe a logo, business or even a document
                            </h1>

                            <div className="mt-20">
                                <h2 className="text-sm mb-1 text-left w-full text-[#E4E5E7]">What would you like to create today</h2>

                                {/* Feature Cards */}
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                    {/* PRD Card */}
                                    <div
                                        className="bg-[#FFF1EF] bg-opacity-10 p-6 rounded-lg border border-pink-100 border-opacity-10 text-left cursor-pointer hover:bg-opacity-20"
                                        onClick={() => handleOptionSelect("prd")}
                                    >
                                        <div className="bg-[#FFF1EF] bg-opacity-20 w-10 h-10 rounded-md flex items-center justify-center mb-4">
                                            <Image src={Idea} alt="Design Icon" width={40} height={40} />
                                        </div>
                                        <h3 className="font-bold text-[#FFFFFF] mb-2">Get a PRD for Your Idea</h3>
                                        <p className="text-[#A0A0A0] text-sm">
                                            Turn your startup idea into a structured PRD in seconds!
                                        </p>
                                    </div>

                                    {/* Name Card */}
                                    <div
                                        className="bg-[#FFF1EF] bg-opacity-10 p-6 rounded-lg border border-pink-100 border-opacity-10 text-left cursor-pointer hover:bg-opacity-20"
                                        onClick={() => handleOptionSelect("name")}
                                    >
                                        <div className="bg-[#FFF1EF] bg-opacity-20 w-10 h-10 rounded-md flex items-center justify-center mb-4">
                                            <Image src={Business} alt="Design Icon" width={40} height={40} />
                                        </div>
                                        <h3 className="font-bold text-[#FFFFFF] mb-2">Get a name for your business</h3>
                                        <p className="text-[#A0A0A0] text-sm">
                                            Find the perfect name for your startup.
                                        </p>
                                    </div>

                                    {/* Logo Card */}
                                    <div
                                        className="bg-[#FFF1EF] bg-opacity-10 p-6 rounded-lg border border-pink-100 border-opacity-10 text-left cursor-pointer hover:bg-opacity-20"
                                        onClick={() => handleOptionSelect("logo")}
                                    >
                                        <div className="bg-[#FFF1EF] bg-opacity-20 w-10 h-10 rounded-md flex items-center justify-center mb-4">
                                            <Image src={BusinessLogo} alt="Design Icon" width={40} height={40} />
                                        </div>
                                        <h3 className="font-bold text-[#FFFFFF] mb-2">Get a Logo for your business</h3>
                                        <p className="text-[#A0A0A0] text-sm">
                                            Describe your business, and we'll generate logo ideas!
                                        </p>
                                    </div>
                                </div>
                            </div>

                            {/* Input Area */}
                            <form onSubmit={handleSubmit}>
                                <input
                                    type="text"
                                    value={inputValue}
                                    onChange={(e) => setInputValue(e.target.value)}
                                    placeholder="Type something..."
                                    className="w-full py-4 px-6 my-6 rounded-full bg-gray-800 text-white border border-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-600"
                                    disabled={isLoading}
                                />
                                {/* Powered by section */}
                                <div className="mt-6 text-center text-gray-400 text-sm">
                                    Powered by <span className="font-bold">
                                    <Image src={A} alt="Design Icon" width={40} height={40} />
                                        </span>enture studio
                                </div>
                            </form>
                        </div>
                    </>
                ) : (
                    /* Chat Interface - Shown when chat is active */
                    <div className="max-w-3xl w-full flex flex-col h-[80vh]">
                        {/* Chat Messages */}
                        <div className="flex-1 overflow-y-auto mb-4 px-2">
                            {messages.map((message, index) => (
                                <div
                                    key={index}
                                    className={`mb-6 ${message.type === 'user' ? 'text-right' : 'text-left'}`}
                                >
                                    <div
                                        className={`inline-block rounded-xl p-4 max-w-[80%] ${message.type === 'user'
                                            ? 'bg-gray-700 text-white rounded-br-none'
                                            : 'bg-gray-600 bg-opacity-40 text-white rounded-bl-none'
                                            }`}
                                    >
                                        {message.content.split('\n').map((text, i) => (
                                            <p key={i} className={i > 0 ? 'mt-2' : ''}>{text}</p>
                                        ))}
                                    </div>
                                </div>
                            ))}
                            {isLoading && (
                                <div className="text-left mb-6">
                                    <div className="inline-block rounded-xl p-4 bg-gray-600 bg-opacity-40 text-white rounded-bl-none">
                                        <p>Thinking...</p>
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Input Area */}
                        <form onSubmit={handleSubmit} className="relative">
                            <input
                                type="text"
                                value={inputValue}
                                onChange={(e) => setInputValue(e.target.value)}
                                placeholder="Type something..."
                                className="w-full py-4 px-6 rounded-full bg-gray-800 text-white border border-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-600"
                                disabled={isLoading}
                            />
                        </form>
                    </div>
                )}


            </div>
        </div>
    );
};

export default BusinessNameGenerator;